import{_ as i,c as a,o as e,ag as n}from"./chunks/framework.ymCRTBvy.js";const k=JSON.parse('{"title":"18.5_逃逸闭包escaping","description":"","frontmatter":{},"headers":[],"relativePath":"swift/basics/18.5_逃逸闭包escaping.md","filePath":"swift/basics/18.5_逃逸闭包escaping.md"}'),t={name:"swift/basics/18.5_逃逸闭包escaping.md"};function l(p,s,h,r,o,c){return e(),a("div",null,s[0]||(s[0]=[n('<h1 id="_18-5-逃逸闭包escaping" tabindex="-1">18.5_逃逸闭包escaping <a class="header-anchor" href="#_18-5-逃逸闭包escaping" aria-label="Permalink to &quot;18.5_逃逸闭包escaping&quot;">​</a></h1><h2 id="逃逸闭包-让你的闭包-逃离-函数-🚀" tabindex="-1">逃逸闭包：让你的闭包“逃离”函数 🚀 <a class="header-anchor" href="#逃逸闭包-让你的闭包-逃离-函数-🚀" aria-label="Permalink to &quot;逃逸闭包：让你的闭包“逃离”函数 🚀&quot;">​</a></h2><p>在 Swift 中，闭包是非常强大的工具，可以让你编写更灵活、更简洁的代码。但是，有时候闭包的生命周期会超出其被定义的函数范围，这时就需要用到 <code>@escaping</code> 标记。让我们一起深入了解逃逸闭包吧！</p><h2 id="什么是逃逸闭包-🤔" tabindex="-1">什么是逃逸闭包？ 🤔 <a class="header-anchor" href="#什么是逃逸闭包-🤔" aria-label="Permalink to &quot;什么是逃逸闭包？ 🤔&quot;">​</a></h2><p>简单来说，当一个闭包作为参数传递给函数，并且在函数返回<em>之后</em>才被调用，那么这个闭包就称为逃逸闭包。这意味着闭包的生命周期超过了函数本身。你可以想象成闭包“逃离”了函数的作用域。</p><ul><li><strong>非逃逸闭包 (默认):</strong> 函数执行结束前调用。</li><li><strong>逃逸闭包:</strong> 函数执行结束后调用。</li></ul><h2 id="为什么要使用-escaping-🧐" tabindex="-1">为什么要使用 <code>@escaping</code>？ 🧐 <a class="header-anchor" href="#为什么要使用-escaping-🧐" aria-label="Permalink to &quot;为什么要使用 `@escaping`？ 🧐&quot;">​</a></h2><p>Swift 需要知道闭包是否会逃逸，以便进行内存管理。当闭包逃逸时，它需要被存储在堆上，而不是栈上。使用 <code>@escaping</code> 告诉编译器，这个闭包会逃逸，编译器会采取相应的措施来确保内存安全。如果不使用 <code>@escaping</code>，编译器可能会报错，或者导致程序崩溃。</p><h2 id="如何使用-escaping-✍️" tabindex="-1">如何使用 <code>@escaping</code>？ ✍️ <a class="header-anchor" href="#如何使用-escaping-✍️" aria-label="Permalink to &quot;如何使用 `@escaping`？ ✍️&quot;">​</a></h2><p>使用 <code>@escaping</code> 非常简单。只需要在闭包类型的参数前面加上 <code>@escaping</code> 关键字即可。例如：</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> doSomething</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">completionHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@escaping</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DispatchQueue.main.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">asyncAfter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">deadline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        completionHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2秒后调用闭包</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>在这个例子中，<code>completionHandler</code> 是一个逃逸闭包，因为它在 <code>doSomething</code> 函数返回后 2 秒才被调用。</p><h2 id="逃逸闭包的常见场景-🗺️" tabindex="-1">逃逸闭包的常见场景 🗺️ <a class="header-anchor" href="#逃逸闭包的常见场景-🗺️" aria-label="Permalink to &quot;逃逸闭包的常见场景 🗺️&quot;">​</a></h2><p>逃逸闭包在异步编程中非常常见。以下是一些常见的场景：</p><ol><li><strong>网络请求:</strong> 当你发起一个网络请求时，通常会使用一个闭包来处理请求完成后的结果。这个闭包通常是逃逸闭包，因为它在请求完成时才被调用，而请求完成的时间可能在函数返回之后。</li><li><strong>定时器:</strong> 当你使用定时器时，通常会使用一个闭包来执行定时任务。这个闭包也是逃逸闭包，因为它在定时器触发时才被调用，而定时器触发的时间可能在函数返回之后。</li><li><strong>存储属性:</strong> 逃逸闭包可以赋值给存储属性，延长闭包的生命周期。</li></ol><h2 id="逃逸闭包的注意事项-⚠️" tabindex="-1">逃逸闭包的注意事项 ⚠️ <a class="header-anchor" href="#逃逸闭包的注意事项-⚠️" aria-label="Permalink to &quot;逃逸闭包的注意事项 ⚠️&quot;">​</a></h2><ul><li><strong>循环引用:</strong> 使用逃逸闭包时，需要注意避免循环引用。如果闭包捕获了 <code>self</code>，并且 <code>self</code> 也持有闭包，那么就会形成循环引用，导致内存泄漏。可以使用 <code>[weak self]</code> 或 <code>[unowned self]</code> 来解决循环引用问题。</li><li><strong>内存管理:</strong> 逃逸闭包需要被存储在堆上，因此会增加内存管理的负担。需要确保及时释放不再使用的逃逸闭包，以避免内存泄漏。</li></ul><p>总而言之，<code>@escaping</code> 标记是 Swift 中处理逃逸闭包的关键。理解并正确使用 <code>@escaping</code> 可以帮助你编写更安全、更高效的代码。希望你能掌握逃逸闭包，并在你的 Swift 项目中灵活运用！🎉</p>',18)]))}const g=i(t,[["render",l]]);export{k as __pageData,g as default};
